-- Database: job_sdb
-- Source-derived baseline; connect to the existing named database before running.
-- Fresh empty public schema only. No DROP, ALTER existing data, CREATE DATABASE or seed data.
-- Do not execute against existing tables without review; CREATE TABLE intentionally fails on collisions.
-- UUID IDs generated by Hibernate; IDENTITY maps to GENERATED BY DEFAULT AS IDENTITY.
-- No cross-service FK, SQL defaults for Java values, triggers or ON DELETE CASCADE.
BEGIN;
SET LOCAL search_path = public;

-- Entity source: ats_parrent/services/job-service/src/main/java/fu/ats/entity/Department.java
CREATE TABLE departments (
    id UUID NOT NULL,
    department_name VARCHAR(255) NOT NULL,
    description TEXT,
    manager_id BIGINT,
    CONSTRAINT pk_departments PRIMARY KEY (id)
);

-- Entity source: ats_parrent/services/job-service/src/main/java/fu/ats/entity/Job.java
CREATE TABLE jobs (
    id UUID NOT NULL,
    department_id UUID NOT NULL,
    recruiter_id BIGINT,
    title VARCHAR(500) NOT NULL,
    description TEXT,
    location VARCHAR(500),
    salary_min NUMERIC(15,2),
    salary_max NUMERIC(15,2),
    status VARCHAR(50),
    utm_source VARCHAR(150),
    utm_medium VARCHAR(150),
    deadline TIMESTAMP WITH TIME ZONE,
    published_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_jobs PRIMARY KEY (id),
    CONSTRAINT ck_jobs_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'CLOSED')),
    CONSTRAINT fk_jobs_department_id FOREIGN KEY (department_id) REFERENCES departments (id)
);

-- Đề xuất từ query: JobRepository.existsByTitle(String): equality lookup; không thêm UNIQUE vì entity chưa khai báo.
CREATE INDEX idx_jobs_title ON jobs (title);

-- Đề xuất từ relationship: Job.department @ManyToOne/@JoinColumn: hỗ trợ JOIN nội bộ và tải collection mappedBy phía parent.
CREATE INDEX idx_jobs_department_id ON jobs (department_id);

COMMIT;
